// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL, LogFile} from "../src/PRIVATE_ETH_CELL.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    LogFile logFile;

    function setUp() public {
        logFile = new LogFile();
        c = new PRIVATE_ETH_CELL();
        c.SetLogFile(address(logFile));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        deposit = bound(deposit, 0, 2 ** 128);
        vm.assume(amount <= deposit);

        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Deposit{value: deposit}();

        uint256 balBefore = c.balances(actor);
        uint256 ethBefore = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == ethBefore - amount);
        } else {
            assertTrue(address(c).balance == ethBefore);
        }
        // general rule: a successful Collect always leaves the ledger consistent
        // with the ETH paid out; the mutant never deducts, so on the mutant the
        // ledger stays at balBefore while _am wei left the contract.
        if (ok && balBefore >= amount) {
            assertTrue(c.balances(actor) == balBefore - amount);
        }
    }
}
